import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { addProductIntent } from 'lib/utils/product-intents'

import { ProductIntentContext, ProductKey } from '~/queries/schema/schema-general'

import { ONBOARDING_TOOLS, SELF_DRIVING_INTENT_METADATA, resolveSetup } from '../shared/useCases'
import type { OnboardingUseCaseKey } from '../shared/useCases'
import { useCaseSelectionLogic } from './useCaseSelectionLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface productEnablementStepLogicValues {
    selectedUseCase: OnboardingUseCaseKey | null // useCaseSelectionLogic
    addingTools: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface productEnablementStepLogicActions {
    addExtraTools: (tools: ProductKey[]) => {
        tools: ProductKey[]
    } // useCaseSelectionLogic
    configureUseCase: (useCase: OnboardingUseCaseKey | null) => {
        useCase: OnboardingUseCaseKey | null
    }
    enableTools: (tools: ProductKey[]) => {
        tools: ProductKey[]
    }
    enableToolsFinished: () => {
        value: true
    }
}

export type productEnablementStepLogicType = MakeLogicType<
    productEnablementStepLogicValues,
    productEnablementStepLogicActions
>

export const productEnablementStepLogic = kea<productEnablementStepLogicType>([
    path(['scenes', 'onboarding', 'self-driving', 'productEnablementStepLogic']),

    connect(() => ({
        values: [useCaseSelectionLogic, ['selectedUseCase']],
        actions: [useCaseSelectionLogic, ['addExtraTools']],
    })),

    actions({
        configureUseCase: (useCase: OnboardingUseCaseKey | null) => ({ useCase }),
        enableTools: (tools: ProductKey[]) => ({ tools }),
        enableToolsFinished: true,
    }),

    reducers({
        addingTools: [
            false,
            {
                enableTools: () => true,
                enableToolsFinished: () => false,
            },
        ],
    }),

    listeners(({ actions }) => ({
        configureUseCase: async ({ useCase }) => {
            const setup = resolveSetup(useCase)

            // Register the whole setup's intents - tools and sidebar extras alike - so the sidebar
            // gets populated (UserProductList resolves them through the products registry). The
            // primary was already registered at use-case selection; with no use case, the default
            // setup's primary takes that slot here.
            const primary = setup.primaryProduct
            const productKeys = new Set<ProductKey>([
                ...setup.tools.map((key) => ONBOARDING_TOOLS[key].productKey),
                ...(setup.additionalTools ?? []),
                ...setup.sidebarExtras,
            ])
            if (!useCase) {
                void addProductIntent({
                    product_type: primary,
                    intent_context: ProductIntentContext.ONBOARDING_PRODUCT_SELECTED_PRIMARY,
                    metadata: SELF_DRIVING_INTENT_METADATA,
                })
            }
            for (const productKey of productKeys) {
                if (productKey === primary) {
                    continue
                }
                void addProductIntent({
                    product_type: productKey,
                    intent_context: ProductIntentContext.ONBOARDING_PRODUCT_SELECTED_SECONDARY,
                    metadata: SELF_DRIVING_INTENT_METADATA,
                })
            }
        },
        enableTools: async ({ tools }) => {
            for (const productKey of tools) {
                await addProductIntent({
                    product_type: productKey,
                    intent_context: ProductIntentContext.ONBOARDING_PRODUCT_SELECTED_SECONDARY,
                    metadata: SELF_DRIVING_INTENT_METADATA,
                })
            }
            actions.addExtraTools(tools)
            actions.enableToolsFinished()
        },
    })),
])
